import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 6 · 多设备与长期运行","description":"Hearth Stage 6 开发模块：事件同步、设备能力路由、离线队列、撤销与密钥轮换、备份恢复、长期运维与完整审计。","frontmatter":{"title":"Stage 6 · 多设备与长期运行","description":"Hearth Stage 6 开发模块：事件同步、设备能力路由、离线队列、撤销与密钥轮换、备份恢复、长期运维与完整审计。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6.md","filePath":"delivery/stage-6.md","lastUpdated":1793752688000}'),i={name:"delivery/stage-6.md"};function d(o,t,h,s,n,g){return e(),r("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">MODULE 6 / 7</p><h1 id="stage-6-·-多设备与长期运行" tabindex="-1">Stage 6 · 多设备与长期运行 <a class="header-anchor" href="#stage-6-·-多设备与长期运行" aria-label="Permalink to &quot;Stage 6 · 多设备与长期运行&quot;">​</a></h1><p class="lead">把单机产品扩展为长期驻留、多设备、可迁移、可撤销的个人 Agent OS。多设备不是复制多个 Agent，而是共享一个逻辑身份、事件、记忆和授权。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>单设备安装、恢复、备份、安全与升级路径已经可用。</li><li>事件、lease、fencing token、记忆版本和设备身份有稳定契约。</li><li>多设备不会绕过审批、幂等和撤销边界。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>实现读取与事件同步。</strong> 建立设备身份、cursor、增量同步、冲突处理、事件重放和投影一致性。</li><li><strong>加入能力路由与离线队列。</strong> 按设备能力分配 GUI、文件和执行任务；断网时排队，恢复后幂等重放，不重复副作用。</li><li><strong>完成撤销与密钥轮换。</strong> 处理设备丢失、远程撤销、密钥轮换、会话失效和安全迁移。</li><li><strong>打通备份、恢复与升级。</strong> 支持加密备份、完整恢复、导出/导入、schema migration、执行器版本锁定、升级前检查和回滚。</li><li><strong>建立长期运行能力。</strong> 加入健康检查、资源配额、日志、监控、资源回收、故障恢复和长期数据迁移演练。</li><li><strong>完成系统审计。</strong> 通过所有阶段出口，完成八类任务覆盖审计、安全红队、故障注入、迁移演练、隐私说明、安装器、升级路径和最终评测报告。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><p>每个增量现在按四层阅读：结果与门槛 → 四个实施工作包 → 工程落点与接口 → 验收演练。工作包可以拆给不同开发者并行，但必须按依赖顺序合并；只完成一个包不等于完成增量。</p><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-6/d6-1.html">D6.1</a> 多设备读取与事件同步</td><td>用户在多个设备看到一致任务与产物</td><td>设备身份、cursor、增量同步、重放</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/d6-2.html">D6.2</a> 设备能力路由与离线队列</td><td>任务去合适设备，断网后可恢复</td><td>能力路由、离线队列、幂等重放</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/d6-3.html">D6.3</a> 设备撤销、密钥轮换与安全迁移</td><td>设备丢失可立即撤销，数据可安全迁移</td><td>撤销、轮换、会话失效、迁移演练</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/d6-4.html">D6.4</a> 备份、恢复、迁移与升级</td><td>用户可以完整备份、恢复和升级</td><td>加密备份、schema migration、回滚</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/d6-5.html">D6.5</a> 长期运行、资源调度与运维</td><td>系统可长期驻留，不需要每天维护</td><td>健康检查、配额、监控、资源回收</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/d6-6.html">D6.6</a> 完整审计与发布</td><td>一个可安装、可迁移、可撤销的个人 Agent OS</td><td>八类任务覆盖、红队、故障注入、最终评测</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 一个逻辑 Agent 在多个设备上保持一致，设备切换不丢任务。</li><li>[ ] 离线恢复率达标，设备切换和重试不重复外部副作用。</li><li>[ ] 设备撤销立即可靠，撤销后无法继续审批或接管。</li><li>[ ] 迁移后事件、产物、记忆和技能可验证。</li><li>[ ] 长期运行无内存泄漏、状态漂移或不可解释的权限扩大。</li><li>[ ] 安装、升级、备份、恢复、隐私和数据导出路径完整。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不把多设备做成多个互不一致的 Agent。</li><li>不用同步冲突或离线队列作为重复副作用的借口。</li><li>不在没有迁移演练和撤销能力时宣告系统完成。</li></ul><h2 id="完成之后" tabindex="-1">完成之后 <a class="header-anchor" href="#完成之后" aria-label="Permalink to &quot;完成之后&quot;">​</a></h2><p>完成本模块后，项目进入长期维护与扩展阶段。后续仍会增加任务族、连接器和优化，但基础产品、恢复、安全、审批和迁移能力不再作为“以后补”的欠账。</p>',16)])])}const m=a(i,[["render",d]]);export{u as __pageData,m as default};
